@push('scripts')<script>$(function(){const t=$('#production-return-table'),e=$.fn.dataTable.render.text(),f=$('#production-return-filters'),table=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:'{{ route('wms.production.issue-returns.data') }}',data:d=>{d.status=f.find('.js-wms-filter-status').val();d.date_from=f.find('.js-wms-filter-from').val();d.date_to=f.find('.js-wms-filter-to').val();}},buttons:[window.erpExcelButton(t)],columns:[{data:'document_number',render:e.display},{data:'business_date',render:e.display},{data:'issue_number',render:e.display},{data:'quantity',className:'text-end',render:e.display},{data:'reason',render:e.display},{data:'status_label',render:(v,x,r)=>x==='display'?'<span class="badge '+(r.status==='POSTED'?'app-status-success':r.status==='APPROVED'?'app-status-info':r.status==='REVERSED'?'app-status-warning':r.status==='VOID'?'app-status-danger':'app-status-neutral')+'">'+e.display(v)+'</span>':v},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:(v,x,r)=>{if(x!=='display')return '';let h='<a class="btn btn-sm btn-app-soft" href="'+r.show_url+'" title="ดูรายละเอียด"><i class="bx bx-show"></i></a> ';if(r.can_approve)h+='<button class="btn btn-sm btn-dark js-production-return" data-url="'+r.approve_url+'" data-action="approve" title="อนุมัติ"><i class="bx bx-check"></i></button> ';if(r.can_post)h+='<button class="btn btn-sm btn-dark js-production-return" data-url="'+r.post_url+'" data-action="post" title="ลง Stock"><i class="bx bx-send"></i></button> ';if(r.can_cancel)h+='<button class="btn btn-sm btn-app-danger js-production-return" data-url="'+r.cancel_url+'" data-action="cancel" title="ยกเลิก"><i class="bx bx-x-circle"></i></button> ';if(r.can_delete)h+='<button class="btn btn-sm btn-app-danger js-production-return" data-url="'+r.delete_url+'" data-action="delete" title="ลบร่าง"><i class="bx bx-trash"></i></button>';return h;}}]}));f.on('click','.js-wms-apply-filter,.js-wms-reset-filter',function(){if($(this).hasClass('js-wms-reset-filter'))f.find('select,input').val('');table.ajax.reload();});$(document).on('click','.js-production-return',function(){const b=$(this),a=b.data('action');Swal.fire({icon:'warning',title:a==='approve'?'อนุมัติใบรับคืนวัตถุดิบ?':a==='post'?'ลง Stock ใบรับคืนวัตถุดิบ?':a==='cancel'?'ยกเลิกใบรับคืนวัตถุดิบ?':'ลบร่างใบรับคืน?',input:a==='cancel'?'textarea':undefined,inputLabel:a==='cancel'?'เหตุผลการยกเลิก':undefined,showCancelButton:true,confirmButtonText:'ยืนยัน',cancelButtonText:'ยกเลิก',confirmButtonColor:a==='cancel'||a==='delete'?'#dc3545':undefined}).then(x=>{if(!x.isConfirmed)return;const data={_token:$('meta[name=csrf-token]').attr('content')};if(a==='cancel')data.reason=x.value;$.ajax({url:b.data('url'),type:a==='delete'?'DELETE':'POST',data}).done(r=>{Swal.fire({icon:'success',text:r.msg,timer:1000,showConfirmButton:false});table.ajax.reload(null,false)}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'ดำเนินการไม่สำเร็จ'}));});});});</script>@endpush
